syntax:
For a type alias using typedef:
typedef existing_type alias_name;

For a type alias using 'using' (preferred in modern C++):
using alias_name = existing_type;

code_example:
#include <iostream>
template<typename T>
using StreamSize = std::size_t; // Modern alias for size_t

class StreamBuffer {
public:
    using streamoff = std::ptrdiff_t; // Alias for implementation-defined stream offset type
    using streampos = std::size_t;    // Alias for implementation-defined stream position type
    using io_state = int;             // Alias for integer type representing stream state
    using open_mode = int;            // Alias for integer type representing open modes
    using seek_dir = int;             // Alias for integer type representing seek directions
};

int main() {
    StreamBuffer buf;
    buf.streamoff offset = 10;
    buf.open_mode mode = 0x01; // Example open mode
    std::cout << "Offset: " << offset << ", Mode: " << mode << std::endl;
    return 0;
}
